package com.asmj.marketplace.insurance.service;
import com.asmj.marketplace.insurance.model.InsurancePlan;import com.asmj.marketplace.insurance.repository.InsurancePlanRepository;import com.asmj.marketplace.vendor.repository.VendorRepository;import lombok.RequiredArgsConstructor;import org.springframework.boot.CommandLineRunner;import org.springframework.stereotype.Component;import java.time.Instant;import java.util.*;
@Component @RequiredArgsConstructor public class InsuranceDataSeeder implements CommandLineRunner { final InsurancePlanRepository plans; final VendorRepository vendors; public void run(String...args){if(plans.count()>0)return;var v=vendors.findAll().stream().findFirst().orElse(null);if(v==null)return;Instant now=Instant.now();plans.save(InsurancePlan.builder().vendorId(v.getId()).insurerName("Demo Secure Insurance").planName("Family Health Shield").insuranceType("HEALTH").description("Demo health insurance plan for marketplace testing.").coverageSummary("Hospitalisation and selected medical expenses; verify final policy wording with the insurer.").sumInsured(1000000).premium(8500).premiumFrequency("YEARLY").minEntryAge(18).maxEntryAge(65).city("Bengaluru").benefits(List.of("Hospitalisation cover","Cashless network","Family floater option")).exclusions(List.of("Waiting periods and exclusions apply","Pre-existing conditions subject to policy terms")).claimProcess("Submit claim through insurer channels with required documents.").claimSettlementInfo("Indicative marketplace information only; verify insurer's current claim process and disclosures.").documents(List.of("Identity proof","Address proof","Medical documents if requested")).images(new ArrayList<>()).approved(true).active(true).featured(true).views(0).createdAt(now).updatedAt(now).build());}
}
